using System.Diagnostics.Metrics;

public class AiMetricsReporter
{
    private static readonly Meter s_meter = new("LearnAI.Platform.Metrics", "1.0.0");

    private static readonly Counter<long> s_tokenCounter = s_meter.CreateCounter<long>(
        name: "ai_tokens_consumed_total",
        unit: "tokens",
        description: "Total number of tokens consumed by model completions");

    private static readonly Histogram<double> s_ttftHistogram = s_meter.CreateHistogram<double>(
        name: "ai_time_to_first_token_ms",
        unit: "ms",
        description: "Latency until the first streaming token arrives");

    public void RecordCompletion(
        string model,
        string tenantId,
        int promptTokens,
        int completionTokens,
        double ttftMs)
    {
        // Tag with dimensions for slice-and-dice in dashboards
        var tags = new TagList
        {
            { "model", model },
            { "tenant_id", tenantId }
        };

        s_tokenCounter.Add(promptTokens, new KeyValuePair<string, object?>("token_type", "prompt"), tags[0], tags[1]);
        s_tokenCounter.Add(completionTokens, new KeyValuePair<string, object?>("token_type", "completion"), tags[0], tags[1]);
        s_ttftHistogram.Record(ttftMs, tags);
    }
}
